                workinman_WMSound.playSound("music/stinger_mission_win", 0.5);
                this._tween.tween({
                    target: this,
                    duration: 4.0,
                    overwrite: true,
                    ease: workinman_tween_Ease.linear
                }, {
                    transition: 1
                }).onComplete($bind(this, this._menuMusic));
